from __future__ import annotations

import json
import urllib.request


class Execution:
    name: str = "fetch_event_products"
    description: str = "Retrieves USGS ShakeMap, PAGER, DYFI, ground-failure and impact-text products plus population exposure tables for one event."
    category: str = "data"

    inputs: list[dict] = [
        {"name": "event_id", "type": str},
        {"name": "event_summary", "type": dict},
    ]

    outputs: list[dict] = [
        {"name": "products", "type": dict},
    ]

    parameters: dict = {
        "request_timeout_seconds": {"type": float, "default": 60},
    }

    DETAIL_URL = "https://earthquake.usgs.gov/earthquakes/feed/v1.0/detail/%s.geojson"
    EVENT_PAGE = "https://earthquake.usgs.gov/earthquakes/eventpage/%s"
    USER_AGENT = "hermes-workflow-earthquake-assessment/1.0 (contact: local analyst)"
    PRODUCT_KEYS = ("shakemap", "losspager", "dyfi", "ground-failure", "finite-fault", "moment-tensor", "origin", "impact-text")

    def _coerce(self, value):
        if isinstance(value, str) and value.strip()[:1] in "{[":
            try:
                return json.loads(value)
            except Exception:
                return value
        return value

    def _unwrap(self, inputs, key):
        value = self._coerce(inputs.get(key))
        if isinstance(value, dict) and key in value and isinstance(value[key], dict):
            return value[key]
        return value

    def _fetch(self, url, timeout):
        request = urllib.request.Request(url, headers={"User-Agent": self.USER_AGENT})
        with urllib.request.urlopen(request, timeout=timeout) as response:
            raw = response.read()
            content_type = response.headers.get("Content-Type", "")
        return raw, content_type

    def _fetch_json(self, url, timeout):
        raw, content_type = self._fetch(url, timeout)
        return json.loads(raw.decode("utf-8", "replace")), content_type

    def _preferred(self, entries):
        def stamp(entry):
            value = entry.get("updateTime") or entry.get("lastModified") or 0
            try:
                return int(value)
            except Exception:
                return 0

        return max(entries, key=stamp)

    def run(self, inputs, parameters, context):
        timeout = int(parameters.get("request_timeout_seconds", 60))
        summary = self._unwrap(inputs, "event_summary") or {}
        event_id = inputs.get("event_id") or summary.get("id") or ""
        if isinstance(event_id, dict):
            event_id = event_id.get("event_id", "")
        event_id = str(event_id).strip()
        if not event_id:
            return {"products": {"status": "missing_event_id", "message": "No event id was supplied.", "errors": []}}

        detail_url = self.DETAIL_URL % event_id
        errors: list[dict] = []
        try:
            detail, content_type = self._fetch_json(detail_url, timeout)
        except Exception as exc:
            return {
                "products": {
                    "status": "detail_fetch_failed",
                    "event_id": event_id,
                    "detail_url": detail_url,
                    "errors": [{"source": "USGS event detail", "url": detail_url, "error": "%s: %s" % (type(exc).__name__, exc)}],
                }
            }

        properties = detail.get("properties") or {}
        raw_products = properties.get("products") or {}
        availability: dict = {}
        records: dict = {}

        for key in self.PRODUCT_KEYS:
            entries = raw_products.get(key) or []
            availability[key] = bool(entries)
            if not entries:
                continue
            entry = self._preferred(entries)
            entry_props = entry.get("properties") or {}
            contents = {}
            for name, meta in (entry.get("contents") or {}).items():
                contents[name or "(embedded)"] = (meta or {}).get("url")
            records[key] = {
                "update_time": entry.get("updateTime"),
                "product_url": "%s/%s" % (self.EVENT_PAGE % event_id, "pager" if key == "losspager" else key),
                "contents": contents,
                "properties": entry_props,
            }

        shakemap = None
        if records.get("shakemap"):
            p = records["shakemap"]["properties"]
            shakemap = {
                "max_mmi": p.get("maxmmi"),
                "map_status": p.get("map-status"),
                "event_description": p.get("event-description"),
                "gmice": p.get("gmice"),
                "magnitude": p.get("magnitude"),
                "depth_km": p.get("depth"),
                "latitude": p.get("latitude"),
                "longitude": p.get("longitude"),
                "min_latitude": p.get("minimum-latitude"),
                "max_latitude": p.get("maximum-latitude"),
                "min_longitude": p.get("minimum-longitude"),
                "max_longitude": p.get("maximum-longitude"),
                "update_time": records["shakemap"]["update_time"],
                "product_url": records["shakemap"]["product_url"],
                "raster_url": (records["shakemap"]["contents"] or {}).get("download/mmi.jpg"),
                "info_url": (records["shakemap"]["contents"] or {}).get("download/info.json"),
            }

        pager = None
        if records.get("losspager"):
            p = records["losspager"]["properties"]
            pager = {
                "alert_level": p.get("alertlevel"),
                "max_mmi": p.get("maxmmi"),
                "release": p.get("release"),
                "review_status": p.get("review-status"),
                "update_time": records["losspager"]["update_time"],
                "product_url": records["losspager"]["product_url"],
            }

        dyfi = None
        if records.get("dyfi"):
            p = records["dyfi"]["properties"]
            dyfi = {
                "num_responses": p.get("num-responses") or p.get("numResp"),
                "max_cdi": p.get("maxmmi"),
                "update_time": records["dyfi"]["update_time"],
                "product_url": records["dyfi"]["product_url"],
            }

        ground_failure = None
        if records.get("ground-failure"):
            p = records["ground-failure"]["properties"]
            ground_failure = {
                "landslide_alert": p.get("landslide-alert"),
                "landslide_hazard_value": p.get("landslide-hazard-alert-value"),
                "landslide_hazard_std": p.get("landslide-hazard-std"),
                "landslide_hazard_range_1std": p.get("landslide-hazard-1std"),
                "landslide_hazard_range_2std": p.get("landslide-hazard-2std"),
                "update_time": records["ground-failure"]["update_time"],
                "product_url": records["ground-failure"]["product_url"],
            }

        impact_text = None
        if records.get("impact-text"):
            for _name, url in (records["impact-text"]["contents"] or {}).items():
                if url:
                    try:
                        raw, _ctype = self._fetch(url, timeout)
                        impact_text = {
                            "text": raw.decode("utf-8", "replace").strip(),
                            "url": url,
                            "update_time": records["impact-text"]["update_time"],
                        }
                        break
                    except Exception as exc:
                        errors.append({"source": "impact-text", "url": url, "error": "%s: %s" % (type(exc).__name__, exc)})
            if impact_text is None:
                embedded = None
                for entry in raw_products.get("impact-text") or []:
                    for meta in (entry.get("contents") or {}).values():
                        if isinstance(meta, dict) and meta.get("bytes"):
                            embedded = meta["bytes"]
                if embedded:
                    impact_text = {"text": str(embedded).strip(), "url": detail_url + "#impact-text", "update_time": None}

        exposures = None
        alerts = None
        for key, target in (("json/exposures.json", "exposures"), ("json/alerts.json", "alerts")):
            url = ((records.get("losspager") or {}).get("contents") or {}).get(key)
            if not url:
                continue
            try:
                payload, _ctype = self._fetch_json(url, timeout)
            except Exception as exc:
                errors.append({"source": "PAGER " + key, "url": url, "error": "%s: %s" % (type(exc).__name__, exc)})
                continue
            if target == "exposures":
                exposures = self._parse_exposures(payload, url)
            else:
                alerts = self._parse_alerts(payload, url)

        missing = [key for key, present in availability.items() if not present]
        cities = None
        city_url = ((records.get("losspager") or {}).get("contents") or {}).get("json/cities.json")
        if city_url:
            try:
                payload, _ctype = self._fetch_json(city_url, timeout)
                cities = {
                    "source_url": city_url,
                    "city_source": payload.get("city_source"),
                    "all_cities": payload.get("all_cities") or [],
                    "onepager_cities": payload.get("onepager_cities") or [],
                }
            except Exception as exc:
                errors.append({"source": "PAGER cities", "url": city_url, "error": "%s: %s" % (type(exc).__name__, exc)})

        return {
            "products": {
                "status": "ok" if not errors else "partial",
                "event_id": event_id,
                "detail_url": detail_url,
                "detail_content_type": content_type,
                "event_properties": {
                    "magnitude": properties.get("mag"),
                    "place": properties.get("place"),
                    "time_ms": properties.get("time"),
                    "alert": properties.get("alert"),
                    "tsunami": properties.get("tsunami"),
                    "significance": properties.get("sig"),
                    "mmi": properties.get("mmi"),
                    "felt": properties.get("felt"),
                    "status": properties.get("status"),
                    "url": properties.get("url"),
                },
                "product_availability": availability,
                "missing_products": missing,
                "shakemap": shakemap,
                "pager": pager,
                "dyfi": dyfi,
                "ground_failure": ground_failure,
                "impact_text": impact_text,
                "exposures": exposures,
                "alerts": alerts,
                "cities": cities,
                "product_records": records,
                "errors": errors,
            }
        }

    def _parse_exposures(self, payload, url):
        population = payload.get("population_exposure") or {}
        economic = payload.get("economic_exposure") or {}
        mmi_bins = population.get("mmi") or economic.get("mmi") or []
        pop_values = population.get("aggregated_exposure") or []
        econ_values = economic.get("aggregated_exposure") or []

        bins = []
        for index, mmi in enumerate(mmi_bins):
            pop = pop_values[index] if index < len(pop_values) else None
            econ = econ_values[index] if index < len(econ_values) else None
            bins.append({"mmi": mmi, "population": pop, "economic_usd": econ})

        def total(values):
            numbers = [float(v) for v in values if isinstance(v, (int, float))]
            return sum(numbers) if numbers else None

        def sum_from(bin_list, threshold, field):
            numbers = [
                float(item[field])
                for item in bin_list
                if isinstance(item.get(field), (int, float)) and item.get("mmi") is not None and float(item["mmi"]) >= threshold
            ]
            return sum(numbers) if numbers else None

        countries = []
        for item in population.get("country_exposures") or []:
            countries.append({"country_code": item.get("country_code"), "population_by_mmi": item.get("exposure")})
        econ_countries = []
        for item in economic.get("country_exposures") or []:
            econ_countries.append({"country_code": item.get("country_code"), "usd_by_mmi": item.get("exposure")})

        return {
            "source_url": url,
            "mmi_bins": bins,
            "total_population_exposed": total(pop_values),
            "population_exposed_mmi6plus": sum_from(bins, 6, "population"),
            "population_exposed_mmi7plus": sum_from(bins, 7, "population"),
            "population_exposed_mmi8plus": sum_from(bins, 8, "population"),
            "total_economic_exposure_usd": total(econ_values),
            "economic_exposure_mmi7plus_usd": sum_from(bins, 7, "economic_usd"),
            "maximum_border_mmi": population.get("maximum_border_mmi"),
            "countries": countries,
            "economic_countries": econ_countries,
        }

    def _parse_alerts(self, payload, url):
        output = {"source_url": url}
        for kind in ("fatality", "economic"):
            item = payload.get(kind)
            if not isinstance(item, dict):
                output[kind] = None
                continue
            bins = item.get("bins") or []
            best = None
            for b in bins:
                probability = b.get("probability")
                if isinstance(probability, (int, float)) and (best is None or probability > best.get("probability", 0)):
                    best = {"color": b.get("color"), "min": b.get("min"), "max": b.get("max"), "probability": probability}
            output[kind] = {
                "level": item.get("level"),
                "units": item.get("units"),
                "expected_value": item.get("gvalue"),
                "most_likely_bin": best,
                "bins": bins,
            }
        return output

    def build_output(self, inputs, parameters, context):
        return self.run(inputs, parameters, context)

from __future__ import annotations

import json
import math


class Execution:
    name: str = "analyze_seismic_impact"
    description: str = "Combines ShakeMap intensity, PAGER exposure, DYFI, ground-failure and city exposure into a seismic impact assessment."
    category: str = "processing"

    inputs: list[dict] = [
        {"name": "event_summary", "type": dict},
        {"name": "products", "type": dict},
    ]

    outputs: list[dict] = [
        {"name": "seismic_impact", "type": dict},
    ]

    parameters: dict = {
        "significant_shaking_mmi": {"type": float, "default": 6.0},
        "severe_shaking_mmi": {"type": float, "default": 8.0},
    }

    MMI_SCALE = [
        (1, "Not felt", "Not felt except by a very few under especially favourable conditions."),
        (2, "Weak", "Felt only by a few persons at rest, especially on upper floors of buildings."),
        (3, "Weak", "Felt quite noticeably indoors, especially on upper floors, but many people do not recognise it as an earthquake."),
        (4, "Light", "Felt indoors by many, outdoors by few. Dishes, windows and doors disturbed; walls make cracking sounds."),
        (5, "Moderate", "Felt by nearly everyone; many awakened. Some dishes and windows broken; unstable objects overturned."),
        (6, "Strong", "Felt by all; many frightened. Slight damage in poorly built structures."),
        (7, "Very strong", "Damage negligible in well-built structures, slight to moderate in ordinary structures."),
        (8, "Severe", "Damage slight in specially designed structures, considerable in ordinary substantial buildings; fall of chimneys."),
        (9, "Violent", "Damage considerable in specially designed structures; well-designed frame structures thrown out of plumb."),
        (10, "Extreme", "Some well-built wooden structures destroyed; most masonry and frame structures destroyed with foundations."),
        (11, "Extreme", "Few, if any, structures remain standing. Bridges destroyed. Broad fissures in ground."),
        (12, "Extreme", "Damage total. Waves seen on ground surfaces. Lines of sight and level distorted."),
    ]

    def _coerce(self, value):
        if isinstance(value, str) and value.strip()[:1] in "{[":
            try:
                return json.loads(value)
            except Exception:
                return value
        return value

    def _unwrap(self, inputs, key):
        value = self._coerce(inputs.get(key))
        if isinstance(value, dict) and key in value and isinstance(value[key], dict):
            return value[key]
        return value

    def _number(self, value):
        if isinstance(value, bool):
            return None
        if isinstance(value, (int, float)):
            return float(value)
        if isinstance(value, str):
            try:
                return float(value.strip())
            except Exception:
                return None
        return None

    def _roman(self, value):
        numerals = [(10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")]
        text = ""
        remaining = int(value)
        for amount, symbol in numerals:
            while remaining >= amount:
                text += symbol
                remaining -= amount
        return text

    def _mmi_label(self, mmi):
        if mmi is None:
            return None
        rounded = max(1, min(12, int(round(mmi))))
        for level, label, description in self.MMI_SCALE:
            if level == rounded:
                return {"mmi": rounded, "roman": self._roman(rounded), "label": label, "description": description}
        return None

    def _haversine_km(self, lat1, lon1, lat2, lon2):
        radius = 6371.0088
        phi1, phi2 = math.radians(lat1), math.radians(lat2)
        d_phi = phi2 - phi1
        d_lambda = math.radians(lon2 - lon1)
        a = math.sin(d_phi / 2) ** 2 + math.cos(phi1) * math.cos(phi2) * math.sin(d_lambda / 2) ** 2
        return 2 * radius * math.asin(min(1.0, math.sqrt(a)))

    def run(self, inputs, parameters, context):
        summary = self._unwrap(inputs, "event_summary") or {}
        products = self._unwrap(inputs, "products") or {}
        significant = float(parameters.get("significant_shaking_mmi", 6.0))
        severe = float(parameters.get("severe_shaking_mmi", 8.0))

        if not isinstance(summary, dict) or not isinstance(products, dict):
            return {"seismic_impact": {"status": "invalid_input", "message": "event_summary and products objects are required."}}

        coordinates = summary.get("coordinates") or {}
        epicentre = {
            "latitude": self._number(coordinates.get("latitude")),
            "longitude": self._number(coordinates.get("longitude")),
            "depth_km": self._number(coordinates.get("depth_km")),
        }

        shakemap = products.get("shakemap") or {}
        pager = products.get("pager") or {}
        dyfi = products.get("dyfi") or {}
        ground_failure = products.get("ground_failure") or {}
        exposures = products.get("exposures") or {}
        alerts = products.get("alerts") or {}
        cities = products.get("cities") or {}

        max_mmi_values = [
            self._number(shakemap.get("max_mmi")),
            self._number(summary.get("dyfi_reported_mmi")),
            self._number(pager.get("max_mmi")),
        ]
        max_mmi = max([v for v in max_mmi_values if v is not None], default=None)

        shaking = {
            "max_mmi": max_mmi,
            "max_mmi_label": self._mmi_label(max_mmi),
            "shakemap_max_mmi": self._number(shakemap.get("max_mmi")),
            "dyfi_max_cdi": self._number(dyfi.get("max_cdi")),
            "pager_max_mmi": self._number(pager.get("max_mmi")),
            "mapping_status": shakemap.get("map_status"),
            "ground_motion_model": shakemap.get("gmice"),
            "shakemap_product_url": shakemap.get("product_url"),
            "shakemap_raster_url": shakemap.get("raster_url"),
            "significant_threshold_mmi": significant,
            "severe_threshold_mmi": severe,
        }

        footprint = None
        min_lat = self._number(shakemap.get("min_latitude"))
        max_lat = self._number(shakemap.get("max_latitude"))
        min_lon = self._number(shakemap.get("min_longitude"))
        max_lon = self._number(shakemap.get("max_longitude"))
        if None not in (min_lat, max_lat, min_lon, max_lon):
            height_km = self._haversine_km(min_lat, min_lon, max_lat, min_lon)
            width_km = self._haversine_km(min_lat, min_lon, min_lat, max_lon)
            footprint = {
                "bbox": [min_lon, min_lat, max_lon, max_lat],
                "approx_width_km": round(width_km, 1),
                "approx_height_km": round(height_km, 1),
                "approx_area_km2": round(width_km * height_km, 1),
                "source": "ShakeMap contour extent (PGA/MMI product bounds)",
            }

        exposure_table = []
        for item in exposures.get("mmi_bins") or []:
            mmi = self._number(item.get("mmi"))
            population = self._number(item.get("population"))
            economic = self._number(item.get("economic_usd"))
            if mmi is None:
                continue
            exposure_table.append(
                {
                    "mmi": mmi,
                    "population": population,
                    "economic_exposure_usd": economic,
                    "intensity_label": (self._mmi_label(mmi) or {}).get("label"),
                }
            )

        population_total = self._number(exposures.get("total_population_exposed"))
        population_6 = self._number(exposures.get("population_exposed_mmi6plus"))
        population_7 = self._number(exposures.get("population_exposed_mmi7plus"))
        population_8 = self._number(exposures.get("population_exposed_mmi8plus"))

        affected_cities = []
        for city in cities.get("all_cities") or []:
            if not isinstance(city, dict):
                continue
            city_mmi = self._number(city.get("mmi"))
            if city_mmi is None or city_mmi < significant:
                continue
            city_lat = self._number(city.get("lat"))
            city_lon = self._number(city.get("lon"))
            distance_km = None
            if None not in (city_lat, city_lon, epicentre["latitude"], epicentre["longitude"]):
                distance_km = round(
                    self._haversine_km(epicentre["latitude"], epicentre["longitude"], city_lat, city_lon), 1
                )
            city_bbox = None
            if None not in (city_lat, city_lon):
                city_bbox = [round(city_lon - 0.5, 3), round(city_lat - 0.5, 3), round(city_lon + 0.5, 3), round(city_lat + 0.5, 3)]
            affected_cities.append(
                {
                    "name": city.get("name"),
                    "population": self._number(city.get("pop")),
                    "estimated_mmi": round(city_mmi, 2),
                    "distance_from_epicentre_km": distance_km,
                    "latitude": city_lat,
                    "longitude": city_lon,
                    "bbox_1deg": city_bbox,
                }
            )
        affected_cities.sort(key=lambda item: (-(item["estimated_mmi"] or 0), -(item["population"] or 0)))

        pager_assessment = {
            "published_alert_level": pager.get("alert_level"),
            "fatality": (alerts or {}).get("fatality"),
            "economic": (alerts or {}).get("economic"),
            "release_status": pager.get("release"),
            "review_status": pager.get("review_status"),
            "product_url": pager.get("product_url"),
            "interpretation": None,
        }
        fatality = pager_assessment.get("fatality") or {}
        economic = pager_assessment.get("economic") or {}
        if pager.get("alert_level"):
            pager_assessment["interpretation"] = (
                "USGS PAGER assigns overall alert level '%s'; fatality alert '%s' and economic alert '%s'. "
                "Alert levels are probabilistic guidance from a global exposure model, not an observed casualty count."
                % (pager.get("alert_level"), fatality.get("level") or "unknown", economic.get("level") or "unknown")
            )

        dyfi_assessment = {
            "responses": self._number(dyfi.get("num_responses")),
            "max_cdi": self._number(dyfi.get("max_cdi")),
            "product_url": dyfi.get("product_url"),
            "interpretation": None,
        }
        responses = dyfi_assessment["responses"]
        if responses:
            dyfi_assessment["interpretation"] = (
                "%d citizen felt reports received; response count controls the reliability of the community intensity map."
                % int(responses)
            )

        landslide = None
        if ground_failure:
            landslide = {
                "alert_level": ground_failure.get("landslide_alert"),
                "aggregate_hazard": self._number(ground_failure.get("landslide_hazard_value")),
                "hazard_std": self._number(ground_failure.get("landslide_hazard_std")),
                "one_sigma_range": ground_failure.get("landslide_hazard_range_1std"),
                "product_url": ground_failure.get("product_url"),
            }

        limitations = [
            "Shaking values are modelled estimates from the USGS ShakeMap, not direct instrument readings at every location.",
            "Population and economic exposure come from the PAGER global exposure model and are indicative, not a damage survey.",
            "PAGER alert levels and expected values are probabilities over ranges; they are not confirmed casualty or loss figures.",
            "No field reconnaissance, structural survey or remote-sensing damage classification is included in this seismic branch.",
        ]
        if shakemap.get("map_status"):
            limitations.append("ShakeMap product status at retrieval: %s." % shakemap.get("map_status"))
        if responses is not None and responses < 25:
            limitations.append("Only %d DYFI reports were available; community intensity estimates are sparse." % int(responses))
        if not products.get("shakemap"):
            limitations.append("No ShakeMap product was published for this event; intensity values may be absent or provisional.")
        if not products.get("pager"):
            limitations.append("No PAGER product was published for this event; no modelled fatality or economic ranges are available.")

        return {
            "seismic_impact": {
                "status": "ok" if products.get("status") != "detail_fetch_failed" else "products_unavailable",
                "event": {
                    "id": summary.get("id") or products.get("event_id"),
                    "magnitude": summary.get("magnitude"),
                    "magnitude_type": summary.get("magnitude_type"),
                    "place": summary.get("place"),
                    "time_utc": summary.get("time_utc"),
                    "time_ms": summary.get("time_ms"),
                    "url": summary.get("url"),
                    "detail_url": summary.get("detail_url") or products.get("detail_url"),
                    "epicentre": epicentre,
