from __future__ import annotations

import json


class Execution:
    name: str = "analyze_satellite_imagery"
    description: str = "Assesses NASA GIBS scene availability and scene-level statistics without claiming damage detection."
    category: str = "processing"

    inputs: list[dict] = [
        {"name": "imagery", "type": dict},
    ]

    outputs: list[dict] = [
        {"name": "imagery_analysis", "type": dict},
    ]

    parameters: dict = {
        "min_mean_brightness": {"type": float, "default": 40},
        "max_dark_fraction": {"type": float, "default": 0.5},
    }

    def _coerce(self, value):
        if isinstance(value, str) and value.strip()[:1] in "{[":
            try:
                return json.loads(value)
            except Exception:
                return value
        return value

    def _unwrap(self, inputs, key):
        value = self._coerce(inputs.get(key))
        if isinstance(value, dict) and key in value and isinstance(value[key], dict):
            return value[key]
        return value

    def _number(self, value):
        if isinstance(value, bool) or value is None:
            return None
        if isinstance(value, (int, float)):
            return float(value)
        try:
            return float(str(value))
        except Exception:
            return None

    def _classify(self, record, min_mean, max_dark):
        if record.get("status") != "ok":
            return "unavailable", record.get("error") or record.get("reason") or "Image request did not return a valid scene."
        stats = record.get("scene_statistics") or {}
        if not stats.get("available"):
            return "unverified", "Scene retrieved but pixel statistics could not be computed: %s" % stats.get("reason")
        mean = self._number(stats.get("mean_brightness_0_255"))
        dark = self._number(stats.get("dark_pixel_fraction"))
        if dark is not None and dark > max_dark:
            return "limited", "More than %.0f%% of the window is near-black, consistent with a night-side or no-data edge." % (max_dark * 100)
        if mean is not None and mean < min_mean:
            return "limited", "Scene is very dark (mean brightness %.1f/255); visual interpretation would be unreliable." % mean
        bright = self._number(stats.get("bright_pixel_fraction"))
        if bright is not None and bright > 0.35:
            return "usable_with_caution", "Large bright fraction (%.0f%%) suggests extensive cloud or snow cover in the window." % (bright * 100)
        return "usable", "Daylight scene with plausible surface signal; interpretable at 250 m only."

    def run(self, inputs, parameters, context):
        imagery = self._unwrap(inputs, "imagery") or {}
        min_mean = float(parameters.get("min_mean_brightness", 40))
        max_dark = float(parameters.get("max_dark_fraction", 0.5))

        if not isinstance(imagery, dict) or "references" not in imagery:
            return {
                "imagery_analysis": {
                    "status": "no_imagery",
                    "message": "No GIBS imagery references were supplied; satellite assessment cannot proceed.",
                    "damage_detection_performed": False,
                }
            }

        references = imagery.get("references") or []
        by_layer: dict = {}
        enriched = []
        for record in references:
            if not isinstance(record, dict):
                continue
            state, reason = self._classify(record, min_mean, max_dark)
            stats = record.get("scene_statistics") or {}
            item = {
                "layer": record.get("layer"),
                "role": record.get("role"),
                "date": record.get("date"),
                "url": record.get("url"),
                "http_status": record.get("http_status"),
                "bytes": record.get("bytes"),
                "content_type": record.get("content_type"),
                "sha256": record.get("sha256"),
                "scene_statistics": stats,
                "assessment": state,
                "assessment_reason": reason,
            }
            enriched.append(item)
            by_layer.setdefault(record.get("layer") or "unknown", {})[record.get("role") or "unknown"] = item

        layer_summaries = []
        for layer, roles in by_layer.items():
            pre = roles.get("pre_event") or {}
            post = roles.get("post_event") or {}
            pre_stats = pre.get("scene_statistics") or {}
            post_stats = post.get("scene_statistics") or {}
            delta = None
            if pre_stats.get("available") and post_stats.get("available"):
                pre_mean = self._number(pre_stats.get("mean_brightness_0_255"))
                post_mean = self._number(post_stats.get("mean_brightness_0_255"))
                if pre_mean is not None and post_mean is not None:
                    delta = round(post_mean - pre_mean, 2)
            layer_summaries.append(
                {
                    "layer": layer,
                    "pre_event": {"date": pre.get("date"), "assessment": pre.get("assessment"), "mean_brightness": (pre_stats or {}).get("mean_brightness_0_255")},
                    "post_event": {"date": post.get("date"), "assessment": post.get("assessment"), "mean_brightness": (post_stats or {}).get("mean_brightness_0_255")},
                    "brightness_delta_post_minus_pre": delta,
                    "comparable_pair": bool(pre.get("assessment") in ("usable", "usable_with_caution") and post.get("assessment") in ("usable", "usable_with_caution")),
                }
            )

        usable_pairs = sum(1 for item in layer_summaries if item["comparable_pair"])
        usable_scenes = sum(1 for item in enriched if item["assessment"] in ("usable", "usable_with_caution"))
        total_scenes = len(enriched)

        limitations = [
            "No damage detection, change detection or building-level classification was performed on these images; nothing in this report asserts that damage is visible.",
            "NASA GIBS true-colour composites are 250 m daily browse imagery, coarser than the size of individual buildings or roads.",
            "Daily composites mix cloud-free and cloudy pixels; the brightness statistics describe the whole window and cannot separate cloud, snow, shadow and surface change.",
            "Scene statistics are scene-level descriptors (mean brightness, spread, dark and bright pixel fractions) used only to judge whether an image is interpretable.",
            "No radiometric normalisation, co-registration or atmospheric correction was applied across the pre-event and post-event dates.",
        ]
        if usable_pairs == 0:
            limitations.append("No layer yielded an interpretable pre-event and post-event pair, so no temporal comparison of imagery is possible.")

        recommendations = [
            "Obtain Sentinel-2 MSI (10 m) or Landsat 8/9 OLI (30 m) scenes for the same footprint, which are suitable for visual damage screening.",
            "Task or purchase commercial high-resolution optical imagery (sub-metre) for populated places inside the highest intensity bands.",
            "Use Sentinel-1 C-band SAR interferometry or amplitude change detection, which is unaffected by cloud cover, to identify surface change.",
            "Cross-check modelled exposure against local administrative population and building-stock records before operational use.",
        ]

        return {
            "imagery_analysis": {
                "status": imagery.get("status"),
                "event_id": imagery.get("event_id"),
                "event_date": imagery.get("event_date"),
                "bbox": imagery.get("bbox"),
                "service": imagery.get("service"),
                "capabilities_url": imagery.get("capabilities_url"),
                "image_size_px": imagery.get("image_size_px"),
                "retrieved_at": imagery.get("retrieved_at"),
                "scenes": enriched,
                "layer_summaries": layer_summaries,
                "availability": {
                    "scenes_requested": total_scenes,
                    "scenes_usable": usable_scenes,
                    "comparable_layer_pairs": usable_pairs,
                    "layers": imagery.get("layers"),
                    "request_errors": imagery.get("errors") or [],
                },
                "damage_detection_performed": False,
                "damage_assessment": "not_attempted",
                "interpretation": (
                    "Imagery confirms whether a daylight true-colour scene exists for the footprint on the chosen dates. "
                    "It supports visual orientation only; it does not establish structural damage, casualties or ground failure."
                ),
                "limitations": limitations,
                "recommended_further_analysis": recommendations,
            }
        }

    def build_output(self, inputs, parameters, context):
        return self.run(inputs, parameters, context)

from __future__ import annotations

import json
from datetime import datetime, timezone


class Execution:
    name: str = "build_disaster_report"
    description: str = "Assembles the final earthquake impact assessment report from the seismic and satellite branches."
    category: str = "utility"

    inputs: list[dict] = [
        {"name": "seismic_impact", "type": dict},
        {"name": "imagery_analysis", "type": dict},
    ]

    outputs: list[dict] = [
        {"name": "report", "type": dict},
    ]

    parameters: dict = {
        "report_title_prefix": {"type": str, "default": "Earthquake Impact Assessment"},
    }

    FDSN_DOC = "https://earthquake.usgs.gov/fdsnws/event/1/"
    PAGER_DOC = "https://earthquake.usgs.gov/data/pager/"
    GIBS_DOC = "https://www.earthdata.nasa.gov/engage/open-data-services-software/earthdata-developer-portal/gibs"

    def _coerce(self, value):
        if isinstance(value, str) and value.strip()[:1] in "{[":
            try:
                return json.loads(value)
            except Exception:
                return value
        return value

    def _unwrap(self, inputs, key):
        value = self._coerce(inputs.get(key))
        if isinstance(value, dict) and key in value and isinstance(value[key], dict):
            return value[key]
        return value

    def _num(self, value, digits=0):
        if isinstance(value, bool) or value is None:
            return "not available"
        try:
            number = float(value)
        except Exception:
            return str(value)
        if digits == 0:
            return "{:,.0f}".format(number)
        return "{:,.{d}f}".format(number, d=digits)

    def _usd(self, value):
        if value is None:
            return "not available"
        try:
            number = float(value)
        except Exception:
            return str(value)
        if number >= 1e9:
            return "USD %.2f billion" % (number / 1e9)
        if number >= 1e6:
            return "USD %.2f million" % (number / 1e6)
        return "USD {:,.0f}".format(number)

    def _table(self, header, rows):
        lines = ["| " + " | ".join(header) + " |", "|" + "|".join(["---"] * len(header)) + "|"]
        for row in rows:
            lines.append("| " + " | ".join(str(cell) for cell in row) + " |")
        return "\n".join(lines)

    def run(self, inputs, parameters, context):
        seismic = self._unwrap(inputs, "seismic_impact") or {}
        imagery = self._unwrap(inputs, "imagery_analysis") or {}
        prefix = parameters.get("report_title_prefix", "Earthquake Impact Assessment")
        generated_at = datetime.now(timezone.utc).isoformat()

        if not isinstance(seismic, dict) or not seismic.get("event"):
            return {
                "report": {
                    "status": "insufficient_data",
                    "generated_at_utc": generated_at,
                    "message": "The seismic branch did not return an event record; no report could be assembled.",
                    "seismic_status": (seismic or {}).get("status"),
                    "imagery_status": (imagery or {}).get("status"),
                }
            }

        event = seismic.get("event") or {}
        shaking = seismic.get("shaking") or {}
        exposure = seismic.get("exposure") or {}
        areas = seismic.get("affected_areas") or {}
        estimates = seismic.get("impact_estimates") or {}
        pager = estimates.get("pager") or {}
        dyfi = estimates.get("dyfi") or {}
        landslide = estimates.get("landslide") or {}
        quality = seismic.get("data_quality") or {}

        magnitude = event.get("magnitude")
        place = event.get("place") or "unknown location"
        magnitude_text = self._num(magnitude, 1).rstrip("0").rstrip(".") if magnitude is not None else "?"
        title = "%s: M%s %s" % (prefix, magnitude_text, place)

        event_details = {
            "event_id": event.get("id"),
            "event_url": event.get("url"),
            "detail_api_url": event.get("detail_url"),
            "magnitude": magnitude,
            "magnitude_type": event.get("magnitude_type"),
            "place": event.get("place"),
            "origin_time_utc": event.get("time_utc"),
            "epicentre": event.get("epicentre"),
            "event_type": event.get("event_type"),
            "review_status": event.get("review_status"),
            "tsunami_flag": event.get("tsunami_flag"),
            "significance_score": event.get("significance_score"),
        }

        shaking_section = {
            "maximum_mmi_modelled": shaking.get("max_mmi"),
            "maximum_intensity_label": (shaking.get("max_mmi_label") or {}).get("label"),
            "intensity_effect_description": (shaking.get("max_mmi_label") or {}).get("description"),
            "shakemap_status": shaking.get("mapping_status"),
            "ground_motion_model": shaking.get("ground_motion_model"),
            "shaking_footprint": areas.get("shaking_footprint"),
            "shakemap_product": shaking.get("shakemap_product_url"),
            "shakemap_raster": shaking.get("shakemap_raster_url"),
        }

        impact_estimates = {
            "pager_overall_alert": pager.get("published_alert_level"),
            "fatality": pager.get("fatality"),
            "economic": pager.get("economic"),
            "pager_product": pager.get("product_url"),
            "dyfi_reports": dyfi.get("responses"),
            "dyfi_max_cdi": dyfi.get("max_cdi"),
            "landslide_hazard": landslide,
            "usgs_impact_text": estimates.get("usgs_impact_text"),
            "usgs_impact_text_url": estimates.get("usgs_impact_text_url"),
        }

        exposure_section = {
            "total_population_exposed": exposure.get("total_population_exposed"),
            "population_mmi6plus": exposure.get("population_exposed_mmi6plus"),
            "population_mmi7plus": exposure.get("population_exposed_mmi7plus"),
            "population_mmi8plus": exposure.get("population_exposed_mmi8plus"),
            "total_economic_exposure_usd": exposure.get("total_economic_exposure_usd"),
            "economic_exposure_mmi7plus_usd": exposure.get("economic_exposure_mmi7plus_usd"),
            "bands": exposure.get("table"),
            "countries": areas.get("country_exposure"),
            "affected_cities": areas.get("affected_cities"),
            "city_source": areas.get("city_source"),
            "source_url": exposure.get("source_url"),
            "note": exposure.get("note"),
        }

        imagery_references = []
        for scene in imagery.get("scenes") or []:
            if not isinstance(scene, dict):
                continue
            stats = scene.get("scene_statistics") or {}
            imagery_references.append(
                {
                    "layer": scene.get("layer"),
                    "role": scene.get("role"),
                    "observation_date": scene.get("date"),
                    "assessment": scene.get("assessment"),
                    "assessment_reason": scene.get("assessment_reason"),
                    "url": scene.get("url"),
                    "http_status": scene.get("http_status"),
                    "bytes": scene.get("bytes"),
                    "sha256": scene.get("sha256"),
                    "mean_brightness_0_255": stats.get("mean_brightness_0_255"),
                    "stddev_brightness": stats.get("stddev_brightness"),
                    "dark_pixel_fraction": stats.get("dark_pixel_fraction"),
                    "bright_pixel_fraction": stats.get("bright_pixel_fraction"),
                }
            )

        imagery_section = {
            "service": imagery.get("service"),
            "capabilities_url": imagery.get("capabilities_url"),
            "footprint_bbox": imagery.get("bbox"),
            "image_size_px": imagery.get("image_size_px"),
            "availability": imagery.get("availability"),
            "layer_summaries": imagery.get("layer_summaries"),
            "references": imagery_references,
            "damage_detection_performed": bool(imagery.get("damage_detection_performed")),
            "damage_assessment": imagery.get("damage_assessment"),
            "interpretation": imagery.get("interpretation"),
            "retrieved_at": imagery.get("retrieved_at"),
        }

        data_sources = [
            {
                "name": "USGS FDSN Event Web Service (event discovery)",
                "url": quality.get("event_query_url") or self.FDSN_DOC,
                "format": "GeoJSON",
                "documentation": self.FDSN_DOC,
                "accessed_utc": quality.get("products_retrieved_at"),
            },
            {
                "name": "USGS event detail feed (all products)",
                "url": event.get("detail_api_url"),
                "format": "GeoJSON",
                "documentation": self.FDSN_DOC,
                "accessed_utc": quality.get("products_retrieved_at"),
            },
            {"name": "USGS ShakeMap", "url": shaking.get("shakemap_product_url"), "format": "Product page, GeoTIFF/JPEG/JSON", "documentation": "https://earthquake.usgs.gov/data/shakemap/"},
            {"name": "USGS PAGER loss estimates", "url": pager.get("product_url"), "format": "JSON (alerts, exposures, cities)", "documentation": self.PAGER_DOC, "accessed_utc": quality.get("products_retrieved_at")},
            {"name": "USGS Did You Feel It", "url": dyfi.get("product_url"), "format": "HTML/GeoJSON", "documentation": "https://earthquake.usgs.gov/data/dyfi/"},
            {
                "name": "NASA GIBS WMS (EPSG:4326 best)",
                "url": imagery.get("capabilities_url"),
                "format": "OGC WMS 1.1.1 imagery",
                "documentation": self.GIBS_DOC,
                "accessed_utc": imagery.get("retrieved_at"),
            },
        ]

        limitations = list(seismic.get("limitations") or []) + list(imagery.get("limitations") or [])
        limitations.append(
            "The report combines two independent branches retrieved at nearly the same time; later USGS product revisions can change ShakeMap and PAGER values."
        )

        priority_areas = []
        for city in (areas.get("affected_cities") or [])[:5]:
            priority_areas.append(
                {
                    "name": city.get("name"),
                    "estimated_mmi": city.get("estimated_mmi"),
                    "population": city.get("population"),
                    "latitude": city.get("latitude"),
                    "longitude": city.get("longitude"),
                    "investigation_bbox": city.get("bbox_1deg"),
                    "reason": "Modelled MMI %.2f; imagery tasking and field verification should target this 1-degree window."
                    % float(city.get("estimated_mmi") or 0),
                }
            )

        recommendations = []
        population_7 = exposure.get("population_exposed_mmi7plus")
        cities = areas.get("affected_cities") or []
        if cities:
            top = ", ".join(str(c.get("name")) for c in cities[:3])
            recommendations.append(
                "Prioritise field verification in settlements modelled at MMI 6 or above; the highest modelled values are at %s." % top
            )
        if population_7:
            recommendations.append(
                "%s people are modelled inside MMI 7+ shaking; task structural damage surveys there first." % self._num(population_7)
            )
        landslide_alert = str(landslide.get("alert_level") or "").lower()
        if landslide_alert in ("yellow", "orange", "red"):
            article = "an" if landslide_alert[0] in "aeiou" else "a"
            recommendations.append(
                "USGS ground-failure modelling reports %s %s landslide alert; commission a geotechnical and slope-stability review of steep terrain in the footprint."
                % (article, landslide_alert)
            )
        if not imagery.get("damage_detection_performed"):
            recommendations.append(
                "No automated damage classification exists yet: acquire 10-30 m optical (Sentinel-2/Landsat) and C-band SAR (Sentinel-1) coverage, then run a supervised damage mapping step."
            )
        if (dyfi.get("responses") or 0) < 25:
            recommendations.append("Promote DYFI reporting locally to strengthen the community intensity map.")
        recommendations.extend(imagery.get("recommended_further_analysis") or [])
        recommendations.append(
            "Re-query the USGS event feed after 24 hours to capture reviewed ShakeMap/PAGER updates and any finite-fault revision."
        )

        bands = exposure.get("table") or []
        band_rows = [
            [b.get("mmi"), b.get("intensity_label") or "", self._num(b.get("population")), self._usd(b.get("economic_exposure_usd"))]
            for b in bands
        ]
        footprint = areas.get("shaking_footprint") or {}
        city_rows = [
            [c.get("name"), self._num(c.get("population")), self._num(c.get("estimated_mmi"), 2), self._num(c.get("distance_from_epicentre_km"), 1)]
            for c in (areas.get("affected_cities") or [])[:10]
        ]
        imagery_rows = [
            [r.get("layer"), r.get("role"), r.get("observation_date"), r.get("assessment"), self._num(r.get("mean_brightness_0_255"), 1)]
            for r in imagery_references
        ]

        fatality = pager.get("fatality") or {}
        economic = pager.get("economic") or {}
        most_likely_fatal = fatality.get("most_likely_bin") or {}
        most_likely_econ = economic.get("most_likely_bin") or {}

        markdown = []
        markdown.append("# %s" % title)
        markdown.append("")
        markdown.append("Generated %s by the Hermes Workflow Studio earthquake assessment pipeline." % generated_at)
        markdown.append("")
        markdown.append("## 1. Event details")
        markdown.append("")
        markdown.append("- Event ID: %s" % (event.get("id") or "unknown"))
        markdown.append("- Magnitude: %s %s" % (self._num(magnitude, 1), event.get("magnitude_type") or ""))
        markdown.append("- Location: %s" % place)
        markdown.append("- Origin time (UTC): %s" % (event.get("time_utc") or "unknown"))
        epicentre = event.get("epicentre") or {}
        markdown.append(
            "- Epicentre: %.4f, %.4f at %s km depth"
            % (epicentre.get("latitude") or 0.0, epicentre.get("longitude") or 0.0, self._num(epicentre.get("depth_km"), 1))
        )
        markdown.append("- USGS event page: %s" % (event.get("url") or "not available"))
        markdown.append("")
        markdown.append("## 2. Ground shaking intensity")
        markdown.append("")
        markdown.append(
            "- Maximum modelled intensity: MMI %s (%s)"
            % (self._num(shaking.get("max_mmi"), 2), (shaking.get("max_mmi_label") or {}).get("label") or "unclassified")
        )
        if (shaking.get("max_mmi_label") or {}).get("description"):
            markdown.append("- Expected effects at that intensity: %s" % shaking["max_mmi_label"]["description"])
        if footprint:
            markdown.append(
                "- Shaking footprint: about %s km x %s km (%s km2), bounding box %s"
                % (
                    self._num(footprint.get("approx_width_km"), 1),
                    self._num(footprint.get("approx_height_km"), 1),
                    self._num(footprint.get("approx_area_km2")),
                    footprint.get("bbox"),
                )
            )
        markdown.append(
            "- ShakeMap status: %s; ground-motion model: %s"
            % (shaking.get("mapping_status") or "not available", shaking.get("ground_motion_model") or "not stated")
        )
        markdown.append("")
        markdown.append("## 3. Affected areas and exposure")
        markdown.append("")
        if band_rows:
            markdown.append(self._table(["MMI", "Intensity", "Population", "Economic exposure"], band_rows))
            markdown.append("")
        markdown.append(
            "- Population in MMI 6+: %s | MMI 7+: %s | MMI 8+: %s"
            % (
                self._num(exposure.get("population_exposed_mmi6plus")),
                self._num(exposure.get("population_exposed_mmi7plus")),
                self._num(exposure.get("population_exposed_mmi8plus")),
            )
        )
        markdown.append(
            "- Total economic exposure inside the shaking footprint: %s (MMI 7+ only: %s)"
            % (self._usd(exposure.get("total_economic_exposure_usd")), self._usd(exposure.get("economic_exposure_mmi7plus_usd")))
        )
        if city_rows:
            markdown.append("")
            markdown.append(self._table(["Settlement", "Population", "Modelled MMI", "Distance (km)"], city_rows))
            markdown.append("")
            markdown.append(
                "Settlement population and coordinates from the PAGER city database (%s)." % (areas.get("city_source") or "source not stated")
            )
        markdown.append("")
        markdown.append("## 4. Available impact estimates")
        markdown.append("")
        markdown.append("- PAGER overall alert: %s" % (pager.get("published_alert_level") or "not published"))
        if fatality:
            markdown.append(
                "- Fatality alert: %s; most likely outcome %s-%s %s (probability %s)"
                % (
                    fatality.get("level"),
                    most_likely_fatal.get("min"),
                    most_likely_fatal.get("max"),
                    fatality.get("units") or "fatalities",
                    self._num(most_likely_fatal.get("probability"), 2),
                )
            )
        if economic:
            markdown.append(
                "- Economic alert: %s; most likely loss band %s-%s million USD (probability %s)"
                % (
                    economic.get("level"),
                    most_likely_econ.get("min"),
                    most_likely_econ.get("max"),
                    self._num(most_likely_econ.get("probability"), 2),
                )
            )
        markdown.append("- DYFI community reports: %s (maximum CDI %s)" % (self._num(dyfi.get("responses")), self._num(dyfi.get("max_cdi"), 2)))
        if landslide:
            markdown.append(
                "- Ground failure: landslide alert %s (aggregate hazard %s)"
                % (landslide.get("alert_level") or "not published", self._num(landslide.get("aggregate_hazard"), 1))
            )
        if estimates.get("usgs_impact_text"):
            markdown.append("")
            markdown.append("USGS impact summary (verbatim, %s):" % (estimates.get("usgs_impact_text_url") or "source"))
            markdown.append("")
            markdown.append("> %s" % estimates["usgs_impact_text"].replace("\n", " "))
        markdown.append("")
        markdown.append("## 5. Satellite imagery")
        markdown.append("")
        markdown.append("Service: %s" % (imagery.get("service") or "not available"))
        markdown.append("")
        markdown.append("Footprint requested: %s at %s pixels." % (imagery.get("bbox"), imagery.get("image_size_px")))
        markdown.append("")
        if imagery_rows:
            markdown.append(self._table(["Layer", "Role", "Observation date", "Assessment", "Mean brightness"], imagery_rows))
            markdown.append("")
        markdown.append(
            "Damage detection performed: %s. The imagery branch verifies scene availability and reports scene-level statistics only."
            % ("yes" if imagery.get("damage_detection_performed") else "no")
        )
        for reference in imagery_references:
            markdown.append("")
            markdown.append(
                "- %s (%s, %s): %s"
                % (reference.get("layer"), reference.get("role"), reference.get("observation_date"), reference.get("assessment"))
            )
            markdown.append("  %s" % reference.get("url"))
        markdown.append("")
        markdown.append("## 6. Data sources")
        markdown.append("")
        source_rows = [[s.get("name"), s.get("url") or "", s.get("format") or "", s.get("documentation") or ""] for s in data_sources]
        markdown.append(self._table(["Source", "Endpoint", "Format", "Documentation"], source_rows))
        markdown.append("")
        markdown.append("## 7. Data limitations")
        markdown.append("")
        for item in limitations:
            markdown.append("- %s" % item)
        markdown.append("")
        markdown.append("## 8. Recommended further investigation")
        markdown.append("")
        if priority_areas:
            markdown.append("Priority windows for imagery tasking and field verification:")
            markdown.append("")
            priority_rows = [
                [a.get("name"), self._num(a.get("estimated_mmi"), 2), self._num(a.get("population")), a.get("investigation_bbox")]
                for a in priority_areas
            ]
            markdown.append(self._table(["Settlement", "Modelled MMI", "Population", "1-degree investigation bbox"], priority_rows))
            markdown.append("")
        for item in recommendations:
            markdown.append("- %s" % item)

        report = {
            "status": "ok",
            "title": title,
            "generated_at_utc": generated_at,
            "scope": "Two-branch earthquake impact assessment: USGS seismic products plus NASA GIBS satellite imagery availability.",
            "event_details": event_details,
            "ground_shaking": shaking_section,
            "affected_areas": {
                "place_description": areas.get("place_description"),
                "shaking_footprint": footprint,
                "countries": areas.get("country_exposure"),
                "settlements": areas.get("affected_cities"),
            },
            "exposure_and_loss_model": exposure_section,
            "impact_estimates": impact_estimates,
            "satellite_imagery": imagery_section,
            "data_sources": data_sources,
            "limitations": limitations,
            "priority_investigation_areas": priority_areas,
            "recommended_further_investigation": recommendations,
            "branch_status": {
                "seismic": seismic.get("status"),
                "imagery": imagery.get("status"),
                "seismic_products": seismic.get("product_availability"),
                "missing_products": seismic.get("missing_products"),
                "retrieval_errors": seismic.get("retrieval_errors"),
            },
            "markdown_summary": "\n".join(markdown),
        }
        return {"report": report}

    def build_output(self, inputs, parameters, context):
        return self.run(inputs, parameters, context)

from __future__ import annotations

import hashlib
import json
import re
import urllib.parse
import urllib.request
from datetime import date, datetime, timedelta, timezone


class Execution:
    name: str = "fetch_gibs_imagery"
    description: str = "Retrieves pre-event and post-event NASA GIBS true-colour satellite imagery for the shaking footprint with scene statistics."
    category: str = "data"

    inputs: list[dict] = [
        {"name": "event_summary", "type": dict},
    ]

    outputs: list[dict] = [
        {"name": "imagery", "type": dict},
    ]

    parameters: dict = {
        "pre_event_lead_days": {"type": float, "default": 7},
        "image_width_px": {"type": float, "default": 600},
        "request_timeout_seconds": {"type": float, "default": 90},
    }

    CAPABILITIES_URL = "https://gibs.earthdata.nasa.gov/wms/epsg4326/best/wms.cgi?SERVICE=WMS&REQUEST=GetCapabilities&VERSION=1.1.1"
    GETMAP_URL = "https://gibs.earthdata.nasa.gov/wms/epsg4326/best/wms.cgi"
    USER_AGENT = "hermes-workflow-earthquake-assessment/1.0 (contact: local analyst)"
    LAYERS = [
        ("VIIRS_SNPP_CorrectedReflectance_TrueColor", "VIIRS/Suomi-NPP True Colour, daily composite, 250 m"),
        ("VIIRS_NOAA20_CorrectedReflectance_TrueColor", "VIIRS/NOAA-20 True Colour, daily composite, 250 m"),
        ("MODIS_Terra_CorrectedReflectance_TrueColor", "MODIS/Terra True Colour, daily composite, 250 m"),
        ("MODIS_Aqua_CorrectedReflectance_TrueColor", "MODIS/Aqua True Colour, daily composite, 250 m"),
    ]

    def _coerce(self, value):
        if isinstance(value, str) and value.strip()[:1] in "{[":
            try:
                return json.loads(value)
            except Exception:
                return value
        return value

    def _unwrap(self, inputs, key):
        value = self._coerce(inputs.get(key))
        if isinstance(value, dict) and key in value and isinstance(value[key], dict):
            return value[key]
        return value

    def _fetch(self, url, timeout):
        request = urllib.request.Request(url, headers={"User-Agent": self.USER_AGENT})
        with urllib.request.urlopen(request, timeout=timeout) as response:
            return response.read(), response.headers.get("Content-Type", ""), response.status

    def _time_extent(self, xml_text, layer):
        pattern = re.compile(r"<Layer[^>]*>\s*<Name>" + re.escape(layer) + r"</Name>", re.S)
        for match in pattern.finditer(xml_text):
            block = xml_text[match.start(): match.start() + 4000]
            extent = re.search(r'<Extent name="time"[^>]*>(.*?)</Extent>', block, re.S)
            if extent:
                return extent.group(1).strip()
        return ""

    def _intervals(self, extent):
        spans = []
        for part in extent.split(","):
            pieces = part.strip().split("/")
            if len(pieces) < 2:
                continue
            try:
                start = date.fromisoformat(pieces[0])
                end = date.fromisoformat(pieces[1])
            except Exception:
                continue
            if end < start:
                start, end = end, start
            spans.append((start, end))
        return spans

    def _latest_on_or_before(self, spans, target):
        best = None
        for start, end in spans:
            if start > target:
                continue
            candidate = min(end, target)
            if candidate >= start and (best is None or candidate > best):
                best = candidate
        return best

    def _earliest_on_or_after(self, spans, target, limit):
        best = None
        for start, end in spans:
            if end < target:
                continue
            candidate = max(start, target)
            if candidate <= end and candidate <= limit and (best is None or candidate < best):
                best = candidate
        return best

    def _png_scene_stats(self, raw):
        import struct
        import zlib

        if raw[:8] != b"\x89PNG\r\n\x1a\n":
            return {"available": False, "reason": "payload is not a PNG image"}
        index = 8
        idat = b""
        width = height = None
        bit_depth = colour_type = interlace = None
        while index < len(raw):
            length = struct.unpack(">I", raw[index:index + 4])[0]
            chunk_type = raw[index + 4:index + 8]
            data = raw[index + 8:index + 8 + length]
            index += 12 + length
            if chunk_type == b"IHDR":
                width, height, bit_depth, colour_type, _comp, _filt, interlace = struct.unpack(">IIBBBBB", data)
            elif chunk_type == b"IDAT":
                idat += data
            elif chunk_type == b"IEND":
                break
        if None in (width, height, bit_depth, colour_type, interlace):
            return {"available": False, "reason": "PNG header could not be parsed"}
        if bit_depth != 8 or interlace != 0 or colour_type not in (0, 2, 4, 6):
            return {
                "available": False,
                "reason": "unsupported PNG variant: bit depth %s, colour type %s, interlace %s"
                % (bit_depth, colour_type, interlace),
            }

        channels = {0: 1, 2: 3, 4: 2, 6: 4}[colour_type]
        stride = width * channels
        try:
            raw_data = zlib.decompress(idat)
        except Exception as exc:
            return {"available": False, "reason": "zlib decompression failed: %s" % exc}

        previous = bytearray(stride)
        offset = 0
        total = 0
        total_sq = 0
        dark = 0
        bright = 0
        transparent = 0
        count = 0
        for _row in range(height):
            if offset >= len(raw_data):
                break
            filter_type = raw_data[offset]
            offset += 1
            line = bytearray(raw_data[offset:offset + stride])
            offset += stride
            if len(line) < stride:
                break
            if filter_type == 1:
                for i in range(channels, stride):
                    line[i] = (line[i] + line[i - channels]) & 0xFF
            elif filter_type == 2:
                for i in range(stride):
                    line[i] = (line[i] + previous[i]) & 0xFF
            elif filter_type == 3:
                for i in range(stride):
                    left = line[i - channels] if i >= channels else 0
                    line[i] = (line[i] + ((left + previous[i]) >> 1)) & 0xFF
            elif filter_type == 4:
                for i in range(stride):
                    a = line[i - channels] if i >= channels else 0
                    b = previous[i]
                    c = previous[i - channels] if i >= channels else 0
                    p = a + b - c
                    pa, pb, pc = abs(p - a), abs(p - b), abs(p - c)
                    predictor = a if (pa <= pb and pa <= pc) else (b if pb <= pc else c)
                    line[i] = (line[i] + predictor) & 0xFF
            previous = line

            for pixel in range(width):
                base = pixel * channels
                if channels >= 3:
                    red, green, blue = line[base], line[base + 1], line[base + 2]
                    alpha = line[base + 3] if channels == 4 else 255
                else:
                    red = green = blue = line[base]
                    alpha = line[base + 1] if channels == 2 else 255
                if alpha < 128:
                    transparent += 1
                    continue
                luminance = (red * 299 + green * 587 + blue * 114) // 1000
                total += luminance
                total_sq += luminance * luminance
                if luminance < 20:
                    dark += 1
                elif luminance > 235:
                    bright += 1
                count += 1

        if not count:
            return {"available": False, "reason": "PNG contained no opaque pixels"}
        mean = total / count
        variance = max(0.0, total_sq / count - mean * mean)
        return {
            "available": True,
            "width": width,
            "height": height,
            "colour_type": colour_type,
            "mean_brightness_0_255": round(mean, 2),
            "stddev_brightness": round(variance ** 0.5, 2),
            "dark_pixel_fraction": round(dark / count, 4),
            "bright_pixel_fraction": round(bright / count, 4),
            "transparent_pixel_fraction": round(transparent / (count + transparent), 4),
            "pixels_sampled": count,
            "method": "pure-python PNG decode (zlib + unfilter), luminance = Rec.601",
        }

    def run(self, inputs, parameters, context):
        summary = self._unwrap(inputs, "event_summary") or {}
        if not isinstance(summary, dict) or not summary.get("bbox"):
            return {"imagery": {"status": "missing_event_bbox", "message": "An event_summary with a bounding box is required."}}

        lead_days = int(parameters.get("pre_event_lead_days", 7))
        width_px = int(parameters.get("image_width_px", 600))
        timeout = int(parameters.get("request_timeout_seconds", 90))
        retrieved_at = datetime.now(timezone.utc).isoformat()

        event_date = None
        if summary.get("time_utc"):
            try:
                event_date = datetime.fromisoformat(summary["time_utc"].replace("Z", "+00:00")).date()
            except Exception:
                event_date = None
        if event_date is None:
            event_date = datetime.now(timezone.utc).date()

        bbox = [float(v) for v in summary["bbox"]]
        west, south, east, north = bbox[0], bbox[1], bbox[2], bbox[3]
        span_lon = max(0.5, east - west)
        span_lat = max(0.5, north - south)
        width_px = max(320, min(1400, width_px))
        height_px = int(max(240, min(1200, round(width_px * span_lat / span_lon))))

        pre_target = event_date - timedelta(days=lead_days)
        post_target = event_date + timedelta(days=1)
        today = datetime.now(timezone.utc).date()

        errors: list[dict] = []
        try:
            raw, _content_type, _status = self._fetch(self.CAPABILITIES_URL, timeout)
            capabilities_xml = raw.decode("utf-8", "replace")
        except Exception as exc:
            return {
                "imagery": {
                    "status": "capabilities_unavailable",
                    "capabilities_url": self.CAPABILITIES_URL,
                    "errors": [{"source": "GIBS WMS GetCapabilities", "url": self.CAPABILITIES_URL, "error": "%s: %s" % (type(exc).__name__, exc)}],
                    "retrieved_at": retrieved_at,
                }
            }

        layer_records = []
        references = []
        for layer, description in self.LAYERS:
            extent = self._time_extent(capabilities_xml, layer)
            spans = self._intervals(extent)
            post_event = self._earliest_on_or_after(spans, post_target, today)
            if post_event is None:
                post_event = self._earliest_on_or_after(spans, event_date, today)
            dates = {
                "pre_event": self._latest_on_or_before(spans, pre_target),
                "post_event": post_event,
            }
            layer_records.append(
                {
                    "layer": layer,
                    "description": description,
                    "time_extent": extent,
                    "selected_dates": {k: (v.isoformat() if v else None) for k, v in dates.items()},
                }
            )
            for role, chosen in dates.items():
                if chosen is None:
                    references.append(
                        {
                            "layer": layer,
                            "role": role,
                            "date": None,
                            "status": "no_available_date",
                            "reason": "No %s acquisition date is published in the GIBS time extent for this layer." % role.replace("_", "-"),
                            "layer_description": description,
                        }
                    )
                    continue

                query = urllib.parse.urlencode(
                    {
                        "SERVICE": "WMS",
                        "VERSION": "1.1.1",
                        "REQUEST": "GetMap",
                        "LAYERS": layer,
                        "STYLES": "",
                        "SRS": "EPSG:4326",
                        "BBOX": "%s,%s,%s,%s" % (west, south, east, north),
                        "WIDTH": width_px,
                        "HEIGHT": height_px,
                        "FORMAT": "image/png",
                        "TRANSPARENT": "FALSE",
                        "TIME": chosen.isoformat(),
                    }
                )
                url = "%s?%s" % (self.GETMAP_URL, query)
                record = {
                    "layer": layer,
                    "role": role,
                    "date": chosen.isoformat(),
                    "url": url,
                    "requested_bbox": [west, south, east, north],
                    "requested_size": [width_px, height_px],
                    "layer_description": description,
                }
                try:
                    raw, content_type, status = self._fetch(url, timeout)
                except Exception as exc:
                    record.update({"status": "request_failed", "error": "%s: %s" % (type(exc).__name__, exc)})
                    errors.append({"source": "GIBS GetMap", "url": url, "error": record["error"]})
                    references.append(record)
                    continue

                content_type = content_type or ""
                is_image = "image" in content_type.lower() and raw[:8] == b"\x89PNG\r\n\x1a\n"
                record.update(
                    {
                        "http_status": status,
                        "content_type": content_type,
                        "bytes": len(raw),
                        "sha256": hashlib.sha256(raw).hexdigest(),
                        "status": "ok" if is_image else "invalid_payload",
                    }
                )
                if is_image:
                    record["scene_statistics"] = self._png_scene_stats(raw)
                else:
                    record["preview"] = raw[:160].decode("utf-8", "replace")
                    errors.append(
                        {
                            "source": "GIBS GetMap",
                            "url": url,
                            "error": "Response was not a PNG image (content-type %r)." % content_type,
                        }
                    )
                references.append(record)

        return {
            "imagery": {
                "status": "ok" if references and not errors else ("partial" if references else "no_imagery"),
                "event_id": summary.get("id"),
                "event_date": event_date.isoformat(),
                "bbox": [west, south, east, north],
                "image_size_px": [width_px, height_px],
                "pre_event_target_date": pre_target.isoformat(),
                "post_event_target_date": post_target.isoformat(),
                "capabilities_url": self.CAPABILITIES_URL,
                "service": "NASA Global Imagery Browse Services (GIBS), WMS 1.1.1, EPSG:4326 / best",
                "layers": layer_records,
                "references": references,
                "errors": errors,
                "retrieved_at": retrieved_at,
                "notes": [
                    "GIBS serves daily true-colour composites generated from VIIRS/MODIS radiances; the pixel for a given date is the best daytime observation for that day.",
                    "Pre-event dates target seven days before the origin date; post-event dates target the first published day after the origin date.",
                    "Images are configured for a %d x %d pixel window over the shaking footprint, far coarser than building-level damage mapping." % (width_px, height_px),
                ],
            }
        }

    def build_output(self, inputs, parameters, context):
        return self.run(inputs, parameters, context)
